'use client';

import React, { useRef, useState } from 'react';

interface Props {
  onSuccess: () => void;
}

export default function TOHaejungUpload({ onSuccess }: Props) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [status, setStatus] = useState<{ type: 'success' | 'error'; message: string } | null>(null);
  const [uploading, setUploading] = useState(false);

  const handleUpload = async () => {
    const file = fileRef.current?.files?.[0];
    if (!file) {
      setStatus({ type: 'error', message: '파일을 선택해주세요.' });
      return;
    }
    if (!file.name.endsWith('.xlsx')) {
      setStatus({ type: 'error', message: '.xlsx 파일만 업로드 가능합니다.' });
      return;
    }
    const confirmed = window.confirm('기존 데이터가 모두 교체됩니다. 계속하시겠습니까?');
    if (!confirmed) return;

    setUploading(true);
    setStatus(null);
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await fetch('/api/to-haejung/upload', { method: 'POST', body: formData });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? '업로드 실패');
      setStatus({ type: 'success', message: `${data.count}개 행이 성공적으로 임포트되었습니다.` });
      if (fileRef.current) fileRef.current.value = '';
      onSuccess();
    } catch (err) {
      setStatus({ type: 'error', message: err instanceof Error ? err.message : '업로드 실패' });
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center gap-3">
        <input
          ref={fileRef}
          type="file"
          accept=".xlsx"
          className="block text-sm text-gray-600 file:mr-3 file:py-2 file:px-4 file:rounded file:border-0 file:bg-blue-50 file:text-blue-700 file:cursor-pointer hover:file:bg-blue-100"
        />
        <button
          type="button"
          onClick={handleUpload}
          disabled={uploading}
          className="px-4 py-2 bg-blue-700 text-white text-sm rounded hover:bg-blue-800 disabled:opacity-50"
        >
          {uploading ? '업로드 중...' : '업로드'}
        </button>
      </div>
      {status && (
        <div
          className={`rounded p-3 text-sm ${
            status.type === 'success'
              ? 'bg-green-50 border border-green-200 text-green-800'
              : 'bg-red-50 border border-red-200 text-red-700'
          }`}
        >
          {status.message}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import AdminDashboard from '@/components/AdminDashboard';
import TOHaejungTable from '@/components/TOHaejungTable';
import TOHaejungUpload from '@/components/TOHaejungUpload';
import type { ToHaejungRow } from '@/lib/types';

type Tab = 'submissions' | 'to-haejung';

export default function AdminPage() {
  const [tab, setTab] = useState<Tab>('submissions');
  const [rows, setRows] = useState<ToHaejungRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const loadRows = useCallback(async () => {
    setLoading(true);
    setLoadError(null);
    try {
      const res = await fetch('/api/to-haejung');
      if (!res.ok) throw new Error(`서버 오류 (${res.status})`);
      setRows(await res.json());
    } catch (err) {
      setLoadError(err instanceof Error ? err.message : '데이터 로드 실패');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (tab === 'to-haejung') loadRows();
  }, [tab, loadRows]);

  const handleSave = async (id: number, fields: Record<string, string>) => {
    const res = await fetch(`/api/to-haejung/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(fields),
    });
    if (!res.ok) {
      const data = await res.json();
      throw new Error(data.error ?? '저장 실패');
    }
    setRows((prev) => prev.map((r) => (r.id === id ? { ...r, ...fields } : r)));
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-900">관리자 대시보드</h1>
      </div>

      {/* 탭 */}
      <div className="flex border-b border-gray-200 mb-6">
        <button
          type="button"
          onClick={() => setTab('submissions')}
          className={`px-5 py-2.5 text-sm font-medium -mb-px border-b-2 transition-colors ${
            tab === 'submissions'
              ? 'border-blue-700 text-blue-700'
              : 'border-transparent text-gray-500 hover:text-gray-700'
          }`}
        >
          제출 현황
        </button>
        <button
          type="button"
          onClick={() => setTab('to-haejung')}
          className={`px-5 py-2.5 text-sm font-medium -mb-px border-b-2 transition-colors ${
            tab === 'to-haejung'
              ? 'border-blue-700 text-blue-700'
              : 'border-transparent text-gray-500 hover:text-gray-700'
          }`}
        >
          TO 배정 관리
        </button>
      </div>

      {tab === 'submissions' && <AdminDashboard />}

      {tab === 'to-haejung' && (
        <div className="space-y-6">
          {/* 업로드 섹션 */}
          <div className="bg-white rounded-lg shadow p-5">
            <h2 className="text-base font-semibold text-gray-800 mb-3">Excel 업로드</h2>
            <p className="text-xs text-gray-500 mb-3">
              RAW 데이터 형식(.xlsx)을 업로드하면 기존 TO 배정 데이터가 전체 교체됩니다.
            </p>
            <TOHaejungUpload onSuccess={loadRows} />
          </div>

          {/* 테이블 섹션 */}
          <div className="bg-white rounded-lg shadow p-5">
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-base font-semibold text-gray-800">TO 배정 현황 (편집 가능)</h2>
              <p className="text-xs text-gray-400">셀을 더블클릭하면 편집할 수 있습니다</p>
            </div>
            {loading ? (
              <div className="py-8 text-center text-gray-400 text-sm">로딩 중...</div>
            ) : loadError ? (
              <div className="rounded bg-red-50 border border-red-200 p-4 text-sm text-red-700">
                {loadError}
              </div>
            ) : (
              <TOHaejungTable rows={rows} editable onSave={handleSave} />
            )}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import TOHaejungTable from '@/components/TOHaejungTable';
import type { ToHaejungRow } from '@/lib/types';

export default function HomePage() {
  const [rows, setRows] = useState<ToHaejungRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch('/api/to-haejung')
      .then((r) => {
        if (!r.ok) throw new Error(`서버 오류 (${r.status})`);
        return r.json();
      })
      .then(setRows)
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div className="w-full px-4 py-6">
      <div className="mb-5">
        <h1 className="text-xl font-bold text-gray-900">2027 TO 배정 현황</h1>
        <p className="text-sm text-gray-500 mt-0.5">학과별 교원 TO 배정 현황표</p>
      </div>

      {loading ? (
        <div className="py-12 text-center text-gray-400">데이터를 불러오는 중...</div>
      ) : error ? (
        <div className="rounded bg-red-50 border border-red-200 p-4 text-sm text-red-700">
          {error}
        </div>
      ) : (
        <TOHaejungTable rows={rows} />
      )}
    </div>
  );
}
